// ---- Fog of War controller -------------------------------------------------
const FOG_KEY='hallow-fog-state-v2';
const MAP_KEY='hallow-active-map';
const BLACKOUT_KEY='hallow-player-blackout';
const fogChannel = ('BroadcastChannel' in window) ? new BroadcastChannel('hallowtide-fog-sync') : null;

function getFogStore(){
  try{return JSON.parse(localStorage.getItem(FOG_KEY)||'{}')}catch{return {}}
}
function saveFogStore(store){
  localStorage.setItem(FOG_KEY,JSON.stringify(store));
}
function defaultFogState(){return {base:'covered',ops:[]}}
function fogForMap(name){
  const s=getFogStore();
  return s[name]||defaultFogState();
}
function setFogForMap(name,state,broadcast=true){
  const s=getFogStore();s[name]=state;saveFogStore(s);
  if(broadcast) broadcastFog({type:'fog',map:name,state});
}
function broadcastFog(msg){
  try{if(fogChannel)fogChannel.postMessage(msg)}catch{}
}
function currentMapList(){return MODE==='dm'?DATA.dmMaps:DATA.playerMaps}
function currentMapObj(){
  const maps=currentMapList(),name=localStorage.getItem(MAP_KEY)||maps[0]?.name;
  return maps.find(m=>m.name===name)||maps[0];
}
function playerMapObjByName(name){
  return DATA.playerMaps.find(m=>m.name===name)||DATA.playerMaps[0];
}
function dmMapObjByName(name){
  return DATA.dmMaps.find(m=>m.name===name)||DATA.dmMaps[0];
}
function syncMapSelection(name,broadcast=true){
  localStorage.setItem(MAP_KEY,name);
  if(broadcast)broadcastFog({type:'map',map:name});
}
function syncBlackout(value,broadcast=true){
  localStorage.setItem(BLACKOUT_KEY,value?'1':'0');
  if(broadcast)broadcastFog({type:'blackout',value:!!value});
}

function sizeFogCanvas(canvas,img){
  const rect=img.getBoundingClientRect();
  const ratio=Math.max(1,window.devicePixelRatio||1);
  canvas.style.width=rect.width+'px';
  canvas.style.height=rect.height+'px';
  const w=Math.max(1,Math.round(rect.width*ratio));
  const h=Math.max(1,Math.round(rect.height*ratio));
  if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}
  return {w,h,ratio};
}
function applyFogState(canvas,img,state,dmPreview=false){
  if(!canvas||!img||!img.complete)return;
  const {w,h}=sizeFogCanvas(canvas,img);
  const ctx=canvas.getContext('2d');
  ctx.clearRect(0,0,w,h);
  ctx.save();

  // Player fog is intentionally 100% opaque. DM preview stays translucent.
  if(state.base==='covered'){
    ctx.globalCompositeOperation='source-over';
    ctx.fillStyle=dmPreview?'rgba(5,5,7,.52)':'#000000';
    ctx.fillRect(0,0,w,h);
  }

  for(const op of state.ops||[]){
    if(op.shape==='rect'){
      const x=op.x*w,y=op.y*h,rw=op.w*w,rh=op.h*h;
      if(op.mode==='reveal'){
        ctx.globalCompositeOperation='destination-out';
        ctx.fillStyle='rgba(0,0,0,1)';
        ctx.fillRect(x,y,rw,rh);
      }else{
        ctx.globalCompositeOperation='source-over';
        ctx.fillStyle=dmPreview?'rgba(5,5,7,.52)':'#000000';
        ctx.fillRect(x,y,rw,rh);
      }
      continue;
    }

    const x=op.x*w,y=op.y*h,r=op.r*Math.min(w,h);
    if(op.mode==='reveal'){
      ctx.globalCompositeOperation='destination-out';
      ctx.fillStyle='rgba(0,0,0,1)';
      ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
    }else{
      ctx.globalCompositeOperation='source-over';
      ctx.fillStyle=dmPreview?'rgba(5,5,7,.52)':'#000000';
      ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
    }
  }
  ctx.restore();
}

function applyPlayerCrop(){
  if(MODE!=='player')return;
  const shell=document.getElementById('playerCropShell');
  const stage=document.getElementById('playerFogStage');
  const img=document.getElementById('activeMap');
  if(!shell||!stage||!img)return;
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  const frac=PLAYER_CROP[name]||0.82;
  shell.style.setProperty('--crop-frac',String(frac));
  // Keep natural aspect ratio while clipping the legend panel offscreen.
  const fullW=img.naturalWidth||1536, fullH=img.naturalHeight||1024;
  stage.style.width=(100/frac)+'%';
  shell.style.aspectRatio=(fullW*frac)+' / '+fullH;
}
function redrawFog(){
  const img=document.getElementById('activeMap'),canvas=document.getElementById('fogCanvas');
  if(!img||!canvas)return;
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  const state=fogForMap(name);
  const preview=MODE==='dm' ? (document.getElementById('fogPreviewToggle')?.checked!==false) : false;
  canvas.classList.toggle('hidden',MODE==='dm'&&!preview);
  if(!(MODE==='dm'&&!preview))applyFogState(canvas,img,state,MODE==='dm');
  if(MODE==='player'){
    const blackout=localStorage.getItem(BLACKOUT_KEY)==='1';
    document.getElementById('playerBlackout')?.classList.toggle('hidden',!blackout);
  }
}
function normalizedPoint(ev,img){
  const r=img.getBoundingClientRect();
  return {x:Math.max(0,Math.min(1,(ev.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(ev.clientY-r.top)/r.height))}
}
function addFogOp(mode,x,y){
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  const state=fogForMap(name);
  const img=document.getElementById('activeMap');
  const px=Number(document.getElementById('brushSize')?.value||90);
  const r=px/Math.min(img.clientWidth||1,img.clientHeight||1);
  const last=state.ops[state.ops.length-1];
  // avoid hundreds of redundant points when dragging slowly
  if(last&&last.mode===mode&&Math.hypot(last.x-x,last.y-y)<r*.17)return;
  state.ops.push({mode,x,y,r});
  if(state.ops.length>3000)state.ops=state.ops.slice(-3000);
  setFogForMap(name,state,true);
  redrawFog();
}

function revealRoomAtPoint(x,y,hide=false){
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  const defs=ROOM_REVEALS[name]||[];
  const room=defs.find(r=>x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h);
  if(!room)return false;
  const state=fogForMap(name);
  state.ops.push({
    mode:hide?'hide':'reveal',
    shape:'rect',
    x:room.x,y:room.y,w:room.w,h:room.h,
    room:room.name
  });
  setFogForMap(name,state,true);
  redrawFog();
  const st=document.getElementById('fogSyncStatus');
  if(st)st.textContent=(hide?'Hidden ':'Revealed ')+room.name;
  return true;
}

function setFogBase(base){
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  setFogForMap(name,{base,ops:[]},true);redrawFog();
}
function undoFogOp(){
  const name=localStorage.getItem(MAP_KEY)||currentMapObj()?.name;
  const state=fogForMap(name);
  if(state.ops.length){state.ops.pop();setFogForMap(name,state,true);redrawFog()}
}
function initDmFogInteractions(){
  if(MODE!=='dm')return;
  const stage=document.getElementById('dmFogStage'),img=document.getElementById('activeMap'),cursor=document.getElementById('brushCursor');
  if(!stage||!img)return;
  let down=false,mode='room-reveal';

  const updateCursorStyle=()=>{
    const tool=document.getElementById('fogTool')?.value||'room-reveal';
    if(cursor){
      cursor.classList.toggle('room-tool',tool.startsWith('room-'));
      cursor.classList.toggle('hide-tool',tool.includes('hide'));
    }
  };

  const moveCursor=ev=>{
    const tool=document.getElementById('fogTool')?.value||'room-reveal';
    if(cursor){
      const size=Number(document.getElementById('brushSize')?.value||90);
      cursor.style.width=size*2+'px';cursor.style.height=size*2+'px';
      const r=stage.getBoundingClientRect();
      cursor.style.left=(ev.clientX-r.left)+'px';
      cursor.style.top=(ev.clientY-r.top)+'px';
      cursor.classList.remove('hidden');
      cursor.classList.toggle('room-tool',tool.startsWith('room-'));
      cursor.classList.toggle('hide-tool',tool.includes('hide'));
    }
  };

  stage.addEventListener('pointerenter',ev=>moveCursor(ev));
  stage.addEventListener('pointerleave',()=>{if(cursor)cursor.classList.add('hidden');down=false});
  stage.addEventListener('pointerdown',ev=>{
    if(ev.button!==0)return;
    mode=document.getElementById('fogTool')?.value||'room-reveal';
    const p=normalizedPoint(ev,img);

    if(mode==='room-reveal'||mode==='room-hide'){
      revealRoomAtPoint(p.x,p.y,mode==='room-hide');
      moveCursor(ev);
      ev.preventDefault();
      return;
    }

    down=true;stage.setPointerCapture(ev.pointerId);
    addFogOp(mode==='hide'?'hide':'reveal',p.x,p.y);
    moveCursor(ev);ev.preventDefault();
  });

  stage.addEventListener('pointermove',ev=>{
    moveCursor(ev);
    if(!down)return;
    const tool=document.getElementById('fogTool')?.value||'reveal';
    if(tool==='reveal'||tool==='hide'){
      const p=normalizedPoint(ev,img);
      addFogOp(tool,p.x,p.y);
    }
    ev.preventDefault();
  });

  stage.addEventListener('pointerup',ev=>{down=false;try{stage.releasePointerCapture(ev.pointerId)}catch{}});
  const toolSel=document.getElementById('fogTool');
  if(toolSel)toolSel.addEventListener('change',updateCursorStyle);
  updateCursorStyle();
}
function updateMapImage(name){
  const img=document.getElementById('activeMap');
  if(!img)return;
  const obj=MODE==='dm'?dmMapObjByName(name):playerMapObjByName(name);
  img.src=obj.src;img.alt=obj.name;
  const title=document.getElementById('playerMapTitle');if(title)title.textContent=obj.name;
  img.onload=()=>{applyPlayerCrop();redrawFog();};
}
function receiveFogMessage(msg){
  if(!msg)return;
  if(msg.type==='map'){
    syncMapSelection(msg.map,false);
    const sel=document.getElementById('mapSelect');if(sel)sel.value=msg.map;
    updateMapImage(msg.map);
  }
  if(msg.type==='fog'){
    const s=getFogStore();s[msg.map]=msg.state;saveFogStore(s);
    if((localStorage.getItem(MAP_KEY)||currentMapObj()?.name)===msg.map)redrawFog();
  }
  if(msg.type==='blackout'){syncBlackout(msg.value,false);redrawFog()}
}
if(fogChannel)fogChannel.onmessage=e=>receiveFogMessage(e.data);
window.addEventListener('storage',e=>{
  if(e.key===FOG_KEY||e.key===MAP_KEY||e.key===BLACKOUT_KEY){
    if(e.key===MAP_KEY&&e.newValue)updateMapImage(e.newValue);
    redrawFog();
  }
});
window.addEventListener('resize',()=>redrawFog());
// ---------------------------------------------------------------------------
function render(){
 document.querySelectorAll('.dm-only').forEach(x=>x.classList.toggle('hidden',MODE!=='dm'));
 let h = PAGE==='dashboard'?dashboard():PAGE==='sessions'?sessions():PAGE==='npcs'?npcs():PAGE==='clues'?clues():PAGE==='bestiary'?bestiary():PAGE==='maps'?maps():PAGE==='handouts'?handouts():PAGE==='soundboard'?soundboard():notes();
 if(MODE!=='dm' && ['sessions','npcs','clues','bestiary','soundboard','notes'].includes(PAGE)){PAGE='dashboard';h=dashboard()}
 content.innerHTML=h;
 const hr=document.getElementById('hollowRange'); if(hr)hr.oninput=e=>{hollowing=+e.target.value;sessionStorage.setItem('hollowing',hollowing);render()};
 const nt=document.getElementById('dmnotes'); if(nt)nt.oninput=e=>sessionStorage.setItem('dmnotes',e.target.value);
 const mv=document.getElementById('masterVol');if(mv)mv.oninput=e=>{masterVolume=+e.target.value;sessionStorage.setItem('masterVolume',masterVolume);if(activeAmbience)activeAmbience.volume=masterVolume*ambienceVolume};
 const av=document.getElementById('ambVol');if(av)av.oninput=e=>{ambienceVolume=+e.target.value;sessionStorage.setItem('ambienceVolume',ambienceVolume);if(activeAmbience)activeAmbience.volume=masterVolume*ambienceVolume};
 const cv=document.getElementById('cueVol');if(cv)cv.oninput=e=>{cueVolume=+e.target.value;sessionStorage.setItem('cueVolume',cueVolume)};
 document.querySelectorAll('[data-amb]').forEach(b=>b.onclick=()=>playAmbience(b.dataset.amb));
 document.querySelectorAll('[data-cue]').forEach(b=>b.onclick=()=>playCue(b.dataset.cue));
 document.querySelectorAll('[data-seq]').forEach(b=>b.onclick=()=>sequence(b.dataset.seq));
 const fa=document.getElementById('fadeAmb');if(fa)fa.onclick=()=>stopAmbience(true);
 const ss=document.getElementById('sbStop');if(ss)ss.onclick=stopAll;
 const ms=document.getElementById('mapSelect');
 if(ms){
   ms.onchange=e=>{
     const chosen=e.target.value;
     syncMapSelection(chosen,true);
     updateMapImage(chosen);
     const st=document.getElementById('fogSyncStatus');if(st)st.textContent='Showing '+chosen+' to players';
   };
 }
 const bs=document.getElementById('brushSize');
 if(bs)bs.oninput=e=>{localStorage.setItem('hallow-brush-size',e.target.value);const l=document.getElementById('brushSizeLabel');if(l)l.textContent=e.target.value+'px'};
 const preview=document.getElementById('fogPreviewToggle');if(preview)preview.onchange=redrawFog;
 const undo=document.getElementById('undoFog');if(undo)undo.onclick=undoFogOp;
 const ra=document.getElementById('revealAllFog');if(ra)ra.onclick=()=>{if(confirm('Reveal this entire map to the players?'))setFogBase('revealed')};
 const rf=document.getElementById('resetFog');if(rf)rf.onclick=()=>{if(confirm('Cover this entire player map again?'))setFogBase('covered')};
 const bo=document.getElementById('blackoutPlayers');if(bo)bo.onclick=()=>{
   const now=localStorage.getItem(BLACKOUT_KEY)==='1';syncBlackout(!now,true);bo.textContent=!now?'Restore Players':'Blackout Players';
 };
 const fit=document.getElementById('dmFitMap');if(fit)fit.onclick=()=>document.getElementById('dmFogStage')?.scrollIntoView({behavior:'smooth',block:'start'});
 const pf=document.getElementById('playerFullscreen');if(pf)pf.onclick=()=>{
   const el=document.getElementById('playerFogStage')||document.documentElement;
   if(!document.fullscreenElement)el.requestFullscreen?.();else document.exitFullscreen?.();
 };
 const img=document.getElementById('activeMap');if(img){if(img.complete){applyPlayerCrop();redrawFog();}else img.onload=()=>{applyPlayerCrop();redrawFog();}}
 initDmFogInteractions();
}
setMode(MODE);
